const breaker = new CircuitBreaker({
  failureThreshold: 5,
  // Long enough for the dependency to actually recover. Too short and the
  // breaker becomes a slower way of hammering it.
  resetAfterMs: 30_000,
});

export async function getPrices(skus: string[]): Promise<PriceResult> {
  if (breaker.isOpen()) {
    // Decided in advance, in the design, not by whichever error escaped.
    return degraded(skus, 'circuit-open');
  }

  try {
    const prices = await withRetry(
      () => fetchPrices(skus, { timeoutMs: 800 }),
      {
        attempts: 3,
        // Jitter, not a fixed backoff: synchronised retries from every
        // instance are how a recovering service gets knocked back down.
        delayMs: (n) => Math.round((2 ** n * 100) * (0.5 + Math.random())),
      },
    );

    breaker.recordSuccess();
    await cache.set(skus, prices, { ttlSeconds: 3600 });
    return { prices, stale: false };
  } catch (err) {
    breaker.recordFailure();
    return degraded(skus, err);
  }
}

async function degraded(skus: string[], cause: unknown): Promise<PriceResult> {
  const cached = await cache.getAllowingStale(skus);

  // A stale price the customer can see beats an error page. The flag travels
  // with the data so the UI can say so rather than quietly showing old
  // numbers as though they were current.
  if (cached) {
    log.warn('pricing.degraded', { cause, skus: skus.length });
    return { prices: cached, stale: true };
  }

  // Nothing cached is the one case where failing is the honest answer.
  throw new ServiceUnavailableError('Pricing unavailable', { cause });
}
